return {
    -- Top Pickers & Explorer
    { "<leader><space>", function() Snacks.picker.smart() end,                                   desc = "Smart find files" },
    { "<leader>,",       function() Snacks.picker.buffers() end,                                 desc = "Buffers" },
    { "<leader>/",       function() Snacks.picker.grep() end,                                    desc = "Grep" },
    { "<leader>:",       function() Snacks.picker.command_history() end,                         desc = "Command history" },
    { "<leader>n",       function() Snacks.picker.notifications() end,                           desc = "[N]otification history" },
    { "<leader>e",       function() Snacks.explorer() end,                                       desc = "[E]xplorer" },
    -- find
    { "<leader>fc",      function() Snacks.picker.files({ cwd = vim.fn.stdpath("config") }) end, desc = "[F]ind [C]onfig file" },
    { "<leader>ff",      function() Snacks.picker.files() end,                                   desc = "[F]ind [F]iles" },
    { "<leader>fg",      function() Snacks.picker.git_files() end,                               desc = "[F]ind [G]it files" },
    { "<leader>fp",      function() Snacks.picker.projects() end,                                desc = "[F]ind [P]rojects" },
    { "<leader>fr",      function() Snacks.picker.recent() end,                                  desc = "[F]ind [R]ecent files" },
    -- git
    { "<leader>gb",      function() Snacks.picker.git_log_line() end,                            desc = "[G]it [B]lame line" },
    { "<leader>gc",      function() Snacks.picker.git_branches() end,                            desc = "[G]it [C]heckout branch" },
    { "<leader>gl",      function() Snacks.picker.git_log({ cwd = Snacks.git.get_root() }) end,  desc = "[G]it [L]og" },
    { "<leader>gL",      function() Snacks.picker.git_log() end,                                 desc = "[G]it [L]og (cwd)" },
    { "<leader>gs",      function() Snacks.picker.git_status() end,                              desc = "[G]it [S]tatus" },
    { "<leader>gS",      function() Snacks.picker.git_stash() end,                               desc = "[G]it [S]tash" },
    { "<leader>gd",      function() Snacks.picker.git_diff() end,                                desc = "[G]it [D]iff (hunks)" },
    { "<leader>gf",      function() Snacks.picker.git_log_file() end,                            desc = "[G]it log [F]ile" },
    { "<leader>gB",      function() Snacks.gitbrowse() end,                                      desc = "[G]it [B]rowse (open)",          mode = { "n", "x" } },
    { "<leader>gY",      function() Snacks.gitbrowse({ open = function(url) vim.fn.setreg("+", url) end, notify = false }) end, desc = "[G]it browse cop[Y] URL", mode = { "n", "x" } },
    -- Grep
    { "<leader>sb",      function() Snacks.picker.lines() end,                                   desc = "[S]earch [B]uffer lines" },
    { "<leader>sB",      function() Snacks.picker.grep_buffers() end,                            desc = "[S]earch open [B]uffers (grep)" },
    { "<leader>sw",      function() Snacks.picker.grep_word() end,                               desc = "[S]earch [W]ord or selection", mode = { "n", "x" } },
    -- search
    { '<leader>s"',      function() Snacks.picker.registers() end,                               desc = "[S]earch registers" },
    { '<leader>s/',      function() Snacks.picker.search_history() end,                          desc = "[S]earch history" },
    { "<leader>sa",      function() Snacks.picker.autocmds() end,                                desc = "[S]earch [A]utocmds" },
    { "<leader>sC",      function() Snacks.picker.commands() end,                                desc = "[S]earch [C]ommands" },
    { "<leader>sh",      function() Snacks.picker.help() end,                                    desc = "[S]earch [H]elp pages" },
    { "<leader>sH",      function() Snacks.picker.highlights() end,                              desc = "[S]earch [H]ighlights" },
    { "<leader>si",      function() Snacks.picker.icons() end,                                   desc = "[S]earch [I]cons" },
    { "<leader>sj",      function() Snacks.picker.jumps() end,                                   desc = "[S]earch [J]umps" },
    { "<leader>sk",      function() Snacks.picker.keymaps() end,                                 desc = "[S]earch [K]eymaps" },
    { "<leader>sl",      function() Snacks.picker.loclist() end,                                 desc = "[S]earch [L]ocation list" },
    { "<leader>sm",      function() Snacks.picker.marks() end,                                   desc = "[S]earch [M]arks" },
    { "<leader>sM",      function() Snacks.picker.man() end,                                     desc = "[S]earch [M]an pages" },
    { "<leader>sp",      function() Snacks.picker.lazy() end,                                    desc = "[S]earch [P]lugin specs" },
    { "<leader>sq",      function() Snacks.picker.qflist() end,                                  desc = "[S]earch [Q]uickfix list" },
    { "<leader>sR",      function() Snacks.picker.resume() end,                                  desc = "[S]earch [R]esume" },
    { "<leader>su",      function() Snacks.picker.undo() end,                                    desc = "[S]earch [U]ndo history" },
    { "<leader>uC",      function() Snacks.picker.colorschemes() end,                            desc = "[U]I [C]olorschemes" },
    -- LSP
    { "gd",              function() Snacks.picker.lsp_definitions() end,                         desc = "[G]oto [D]efinition" },
    { "gD",              function() Snacks.picker.lsp_declarations() end,                        desc = "[G]oto [D]eclaration" },
    { "gr",              function() Snacks.picker.lsp_references() end,                          nowait = true,                     desc = "[G]oto [R]eferences" },
    { "gI",              function() Snacks.picker.lsp_implementations() end,                     desc = "[G]oto [I]mplementation" },
    { "gy",              function() Snacks.picker.lsp_type_definitions() end,                    desc = "[G]oto t[Y]pe definition" },
    { "gai",             function() Snacks.picker.lsp_incoming_calls() end,                      desc = "[G]oto c[A]lls [I]ncoming" },
    { "gao",             function() Snacks.picker.lsp_outgoing_calls() end,                      desc = "[G]oto c[A]lls [O]utgoing" },
    { "<leader>sS",      function() Snacks.picker.lsp_symbols() end,                             desc = "[S]earch file [S]ymbols" },
    { "<leader>cd",      function() Snacks.picker.diagnostics() end,                             desc = "[C]ode [D]iagnostics (workspace)" },
    { "<leader>cD",      function() Snacks.picker.diagnostics_buffer() end,                      desc = "[C]ode [D]iagnostics (buffer)" },
    { "<leader>ss",      function() Snacks.picker.lsp_workspace_symbols() end,                   desc = "[S]earch workspace [S]ymbols" },
    -- words (references of the word under cursor)
    { "]]",              function() Snacks.words.jump(vim.v.count1) end,                         desc = "Next reference" },
    { "[[",              function() Snacks.words.jump(-vim.v.count1) end,                        desc = "Previous reference" },
}
